exercise.solution:
a = float(input("Prvi broj: "))
operacija = input("Operacija (+, -, *, /): ")
b = float(input("Drugi broj: "))

# Proveri operaciju i ispiši rezultat.
if operacija == "+":
    print("Rezultat:", a + b)
elif operacija == "-":
    print("Rezultat:", a - b)
elif operacija == "*":
    print("Rezultat:", a * b)
elif operacija == "/":
    if b == 0:
        print("Deljenje nulom nije moguće.")
    else:
        print("Rezultat:", a / b)
else:
    print("Nepoznata operacija.")

